def choose_move(observation):
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    self_pos = observation.get("self_position", (0, 0))
    opp_pos = observation.get("opponent_position", (0, 0))

    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    remaining = observation.get("remaining_resource_count", 0)

    self_path = observation.get("self_path", [])
    opp_path = observation.get("opponent_path", [])

    def dist(a, b):
        ax, ay = a
        bx, by = b
        return abs(ax - bx) + abs(ay - by)

    sx, sy = self_pos
    ox, oy = opp_pos

    closest_r = None
    best_dr = None
    for r in resources:
        rx, ry = r.get("position", (0, 0))
        d = dist((sx, sy), (rx, ry))
        if best_dr is None or d < best_dr:
            best_dr = d
            closest_r = (rx, ry)

    dx = 0
    dy = 0

    if closest_r is not None:
        rx, ry = closest_r
        if rx > sx:
            dx = 1
        elif rx < sx:
            dx = -1
        if ry > sy:
            dy = 1
        elif ry < sy:
            dy = -1
        if dx != 0 and dy != 0:
            if dist((sx + dx, sy), closest_r) > dist((sx, sy + dy), closest_r):
                dx = 0
            else:
                dy = 0

    if dx == 0 and dy == 0:
        # Move away from opponent if possible
        if ox >= sx:
            dx = -1
        elif ox <= sx:
            dx = 1
        if oy >= sy:
            dy = -1
        elif oy <= sy:
            dy = 1
        if dx != 0 and dy != 0:
            if dist((sx + dx, sy), opp_pos) > dist((sx, sy + dy), opp_pos):
                dx = 0
            else:
                dy = 0

    # Bound within grid if provided
    if grid_w and grid_h:
        nx = max(0, min(grid_w - 1, sx + dx))
        ny = max(0, min(grid_h - 1, sy + dy))
        dx = nx - sx
        dy = ny - sy

    return [dx, dy]
